import{_ as i,o as a,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Inking Out Inefficiencies in Ceph Erasure Coding - Alex Ainscow & Bill Scales, IBM","description":"","frontmatter":{"title":"Inking Out Inefficiencies in Ceph Erasure Coding - Alex Ainscow & Bill Scales, IBM","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-19T00:00:00.000Z","tags":["Ceph","Erasure Coding","Storage Optimization","Performance Improvement","Data Efficiency"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Inking_Out_Inefficiencies_in_Ceph_Erasure_Coding_-_Alex_Ainscow_Bill_Scales_IBM.md","filePath":"posts/2025/Inking_Out_Inefficiencies_in_Ceph_Erasure_Coding_-_Alex_Ainscow_Bill_Scales_IBM.md","lastUpdated":1780459816000}'),r={name:"posts/2025/Inking_Out_Inefficiencies_in_Ceph_Erasure_Coding_-_Alex_Ainscow_Bill_Scales_IBM.md"};function n(o,e,s,c,_,u){return a(),l("div",null,[...e[0]||(e[0]=[t('<p>Ceph社区新特性Fast EC（Erasure Coding优化）技术分享会议纪要如下：</p><h3 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h3><p>本次会议重点介绍了Ceph社区新特性Fast EC在Tentacle版本中的改进及未来规划。</p><h3 id="核心议题与讨论内容" tabindex="-1">核心议题与讨论内容 <a class="header-anchor" href="#核心议题与讨论内容" aria-label="Permalink to &quot;核心议题与讨论内容&quot;">​</a></h3><h4 id="erasure-coding-ec-基础回顾" tabindex="-1">Erasure Coding (EC) 基础回顾 <a class="header-anchor" href="#erasure-coding-ec-基础回顾" aria-label="Permalink to &quot;Erasure Coding (EC) 基础回顾&quot;">​</a></h4><ul><li>传统副本（Replica）机制效率低，需要3倍存储空间。</li><li>EC原理：通过数学算法将数据分片（K数据分片 + M编码分片），允许最多M个OSD丢失而不影响数据可用性。</li><li>关键参数：Chunk Size（Stripe Unit）、K/M选择。</li></ul><h4 id="fast-ec的改进目标" tabindex="-1">Fast EC的改进目标 <a class="header-anchor" href="#fast-ec的改进目标" aria-label="Permalink to &quot;Fast EC的改进目标&quot;">​</a></h4><ul><li>性能对标Replica，尤其是在RBD和CephFS场景下。</li><li>成本效益，以更低存储开销接近副本性能。</li></ul><h4 id="fast-ec关键技术优化" tabindex="-1">Fast EC关键技术优化 <a class="header-anchor" href="#fast-ec关键技术优化" aria-label="Permalink to &quot;Fast EC关键技术优化&quot;">​</a></h4><ul><li><strong>读性能优化</strong>：按需读取，消除K值对性能的影响。</li><li><strong>写性能优化</strong>：最小化读写，Parity Delta Write直接更新编码分片。</li><li><strong>存储效率提升</strong>：动态分片分配，支持更大默认值Chunk Size。</li></ul><h4 id="性能对比与实测结果" tabindex="-1">性能对比与实测结果 <a class="header-anchor" href="#性能对比与实测结果" aria-label="Permalink to &quot;性能对比与实测结果&quot;">​</a></h4><ul><li>读性能：小块读取IOPS提升3倍，接近Replica 50%性能。</li><li>写性能：小块写入延迟显著降低，效率提升2-3倍。</li><li>扩展性：性能不受K值影响。</li></ul><h4 id="未来规划-umbrella版本" tabindex="-1">未来规划（Umbrella版本） <a class="header-anchor" href="#未来规划-umbrella版本" aria-label="Permalink to &quot;未来规划（Umbrella版本）&quot;">​</a></h4><ul><li>Direct Reads：客户端直接向OSD请求数据，读性能与Replica持平。</li><li>小对象打包：合并小对象提升存储效率，优化恢复性能。</li><li>非破坏式Pool Migration：支持在线迁移至新EC配置。</li><li>功能补齐：支持OMAP和Classes，简化RBD配置。</li><li>跨站点EC（Stretch Cluster）：探索单EC Pool跨站点或分站点EC副本。</li></ul><h4 id="问答环节关键点" tabindex="-1">问答环节关键点 <a class="header-anchor" href="#问答环节关键点" aria-label="Permalink to &quot;问答环节关键点&quot;">​</a></h4><ul><li>兼容性：Fast EC支持新旧数据格式，需升级OSD/MON，客户端无需强制升级。</li><li>带宽场景：S3大对象场景性能提升约5-10%，随机访问受益更明显。</li><li>资源开销：通过减少IO请求降低CPU和网络负载。</li><li>Pool Migration：后台任务，类似Backfill，提供进度监控。</li></ul><h4 id="行动计划" tabindex="-1">行动计划 <a class="header-anchor" href="#行动计划" aria-label="Permalink to &quot;行动计划&quot;">​</a></h4><ul><li>Tentacle版本：部署Fast EC并测试性能。</li><li>Umbrella版本：评估Direct Reads和Pool Migration特性。</li><li>长期优化：关注小对象打包和跨站点EC方案。</li></ul><p>该总结准确反映了原始内容的要点，涵盖了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。</p>',19)])])}const C=i(r,[["render",n]]);export{d as __pageData,C as default};
